        <script>
function openModal(id) {
    document.getElementById(id).style.display = 'flex';
}
function closeModal(id) {
    document.getElementById(id).style.display = 'none';
}

window.onclick = function(event) {
    if (event.target.classList.contains('modal')) {
        event.target.style.display = 'none';
    }
}

document.addEventListener('click', function(event) {
    if (event.target && event.target.classList.contains('edit-action-btn')) {
        const btn = event.target;
        
        const id = btn.getAttribute('data-id');
        const assetTag = btn.getAttribute('data-tag');
        const name = btn.getAttribute('data-name');
        const categoryId = btn.getAttribute('data-category');
        const qty = btn.getAttribute('data-qty');
        const price = btn.getAttribute('data-price');
        const location = btn.getAttribute('data-location');

        document.getElementById('edit_id').value = id;
        document.getElementById('edit_asset_tag').value = assetTag;
        document.getElementById('edit_name').value = name;
        document.getElementById('edit_category_id').value = categoryId;
        document.getElementById('edit_qty').value = qty;
        document.getElementById('edit_unit_price').value = price;
        document.getElementById('edit_location').value = location;
        
        openModal('editModal');
    }
});

function triggerReturnPortionModal(txId, maxQty, itemName) {
    document.getElementById('return_tx_id').value = txId;
    document.getElementById('return_item_display').value = itemName;
    document.getElementById('return_max_display').value = maxQty + " units outstanding";
    
    const qtyInput = document.getElementById('return_qty_input');
    qtyInput.max = maxQty;
    qtyInput.value = maxQty;
    
    openModal('portionReturnModal');
}

document.getElementById('tableSearch').addEventListener('keyup', function() {
    let filter = this.value.toUpperCase();
    let rows = document.querySelectorAll('#inventoryTable tbody tr');
    
    rows.forEach(row => {
        let text = row.textContent || row.innerText;
        if (text.toUpperCase().indexOf(filter) > -1) {
            row.style.display = "";
        } else {
            row.style.display = "none";
        }
    });
});

const alertBox = document.getElementById('systemAlert');
if(alertBox) {
    setTimeout(() => {
        alertBox.style.transition = "opacity 0.5s ease";
        alertBox.style.opacity = "0";
        setTimeout(() => alertBox.remove(), 500);
    }, 4000);
}
        </script>
    <?php endif; ?>
</body>
